'use strict';

var Complex64 = require( '@stdlib/complex-float32-ctor' );
var discreteUniform = require( '@stdlib/random-base-discrete-uniform' );
var cnegf = require( './../lib' );

function randomComplex() {
	var re = discreteUniform( -50, 50 );
	var im = discreteUniform( -50, 50 );
	return new Complex64( re, im );
}

var z;
var o;
var i;

for ( i = 0; i < 100; i++ ) {
	z = randomComplex();
	o = cnegf( z );
	console.log( 'negate(%s) = %s', z.toString(), o.toString() );
}","lineStart":1,"lineEnd":39,"totalLines":39,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-base-neg/examples/index.js","time":{"start":1783264498808,"end":1783264498811}},"id":"prt_f32d8d368001wQtliUPpg5mwtk","sessionID":"ses_0cd28192cffeUoCRyXDOIRybLh","messageID":"msg_f32d88e98001CraMjlRno53zMN"}}

